/opt/homebrew/bin/zsh -lc "node <<'NODE'
const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');
const checks = {
  productKits: (html.match(/data-bench=\"product-kit-case\"/g) || []).length,
  temperatureLogs: (html.match(/data-bench=\"temperature-log-id\"/g) || []).length,
  depotLanes: (html.match(/data-bench=\"depot-lane-id\"/g) || []).length,
  viewControls: (html.match(/data-bench=\"kit-view-option\"/g) || []).length,
  noteToggle: (html.match(/data-bench=\"pharmacist-note-toggle\"/g) || []).length,
  reviewForms: (html.match(/data-bench=\"release-review-form\"/g) || []).length,
  pendingState: (html.match(/Release review pending/g) || []).length,
  mobileWordBreak: html.includes('word-break:break-all'),
  fixedRegister: html.includes('min-width:1120px'),
  fixedLanes: html.includes('min-width:980px')
};
console.log(JSON.stringify(checks, null, 2));
NODE"

