/opt/homebrew/bin/zsh -lc "node - <<'NODE'
const fs = require('fs');
const vm = require('vm');
const html = fs.readFileSync('index.html', 'utf8');
const script = html.match(/<script>([\\s\\S]*?)<\\/script>/)[1];
new vm.Script(script);
const checks = [
  ['product kits', (html.match(/data-bench=\"product-kit-case\"/g) || []).length, 4],
  ['temperature logs', (html.match(/data-bench=\"temperature-log-id\"/g) || []).length, 6],
  ['depot lanes', (html.match(/data-bench=\"depot-lane-id\"/g) || []).length, 2],
  ['transfer windows', (html.match(/data-bench=\"transfer-window\"/g) || []).length, 2],
  ['view controls', (html.match(/data-view=\"(?:kit-register|depot-lanes|release-review)\" aria-pressed/g) || []).length, 3],
  ['note toggle', (html.match(/data-bench=\"pharmacist-note-toggle\"/g) || []).length, 1],
  ['release form', (html.match(/data-bench=\"release-review-form\"/g) || []).length, 1],
];
for (const [name, actual, expected] of checks) {
  if (actual "'!== expected) throw new Error(`${name}: ${actual}, expected ${expected}`);
}
if (/word-break'"\\s*:\\s*break-all/.test(html)) throw new Error('identifier word-breaking remains');
if ("'!/'"\\.register[\\s\\S]*grid-template-columns: repeat\\(2, minmax\\(0, 1fr\\)/.test(html)) throw new Error('register reflow missing');
if ("'!/'"\\.lanes[\\s\\S]*grid-template-columns: repeat\\(2, minmax\\(0, 1fr\\)/.test(html)) throw new Error('lane reflow missing');
if ("'!/'"\\.decision strong[\\s\\S]*white-space: nowrap/.test(html)) throw new Error('decision target protection missing');
console.log('integrity checks passed');
NODE
sed -n '1,340p' index.html | tail -n 90"

